import { createFileRoute, Outlet, useLocation } from "@tanstack/react-router";
import { AnimatePresence, motion } from "framer-motion";
import {
	ChevronLeft,
	ChevronRight,
	Coffee,
	Globe,
	LayoutDashboard,
	LogOut,
	MoreHorizontal,
	Sparkles,
	User,
	X,
} from "lucide-react";
import { useEffect, useState } from "react";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuLabel,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { APP_VERSION } from "@/lib/version";

// @ts-expect-error - Route will be generated by TanStack Router plugin
export const Route = createFileRoute("/admin")({
	component: AdminLayout,
});

const PAGE_TITLES: Record<string, string> = {
	"/admin": "Dasbor",
	"/admin/booking": "Booking",
};

const BOTTOM_NAV_ITEMS = [
	{ to: "/admin", icon: LayoutDashboard, label: "Dasbor", exact: true },
	{ to: "/admin/booking", icon: Globe, label: "Booking" },
	{ to: "", icon: MoreHorizontal, label: "Lainnya", isMore: true },
];

function AdminLayout() {
	const [isCollapsed, setIsCollapsed] = useState(false);
	const [isQuickMenuOpen, setIsQuickMenuOpen] = useState(false);
	const storeName = "Yumi Admin";
	const appName = "Yumi POS";
	const location = useLocation();
	const currentPageTitle = PAGE_TITLES[location.pathname] || "Admin";

	useEffect(() => {
		setIsQuickMenuOpen(false);
	}, [location.pathname]);

	const handleNavigate = (path: string) => {
		window.location.href = path;
	};

	return (
		<div className="flex h-full w-full overflow-hidden bg-background">
			{/* Desktop Sidebar */}
			<aside
				className={`relative hidden flex-col border-border border-r bg-sidebar text-sidebar-foreground transition-all duration-300 ease-in-out md:flex ${
					isCollapsed ? "w-16" : "w-64"
				}`}
			>
				<div className="flex h-14 items-center gap-2 border-border border-b px-4">
					<div className="shrink-0 rounded-md bg-primary p-1.5">
						<Coffee className="h-4 w-4 text-primary-foreground" />
					</div>
					{!isCollapsed && (
						<span className="truncate font-bold text-base tracking-tight">
							{storeName}
						</span>
					)}
				</div>

				<button
					className="absolute top-20 -right-3 z-10 flex h-6 w-6 items-center justify-center rounded-full border border-border bg-background shadow-sm"
					onClick={() => setIsCollapsed(!isCollapsed)}
					type="button"
				>
					{isCollapsed ? (
						<ChevronRight className="h-3 w-3" />
					) : (
						<ChevronLeft className="h-3 w-3" />
					)}
				</button>

				<nav className="flex-1 space-y-1 p-2">
					<DesktopNavLink
						icon={<Sparkles />}
						isCollapsed={isCollapsed}
						label="Dashboard"
						onClick={() => handleNavigate("/admin")}
					/>
					<DesktopNavLink
						icon={<Globe />}
						isCollapsed={isCollapsed}
						label="Booking"
						onClick={() => handleNavigate("/admin/booking")}
					/>
				</nav>

				<div className="border-border border-t p-2">
					<button
						className={`flex w-full items-center gap-2 rounded-md p-2 text-muted-foreground text-xs transition-colors hover:bg-destructive/10 hover:text-destructive ${
							isCollapsed ? "justify-center" : ""
						}`}
						onClick={() => handleNavigate("/")}
						type="button"
					>
						<LogOut className="h-4 w-4 shrink-0" />
						{!isCollapsed && <span className="font-medium">Keluar</span>}
					</button>
				</div>
			</aside>

			{/* Main Content */}
			<main className="flex flex-1 flex-col overflow-hidden bg-background">
				<header className="flex h-14 shrink-0 items-center justify-between border-border border-b px-4">
					<div className="flex items-center gap-3">
						<div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-primary md:hidden">
							<Coffee className="h-4 w-4 text-primary-foreground" />
						</div>
						<div>
							<h1 className="font-bold text-base leading-tight md:text-lg">
								{currentPageTitle}
							</h1>
							<p className="text-[10px] text-muted-foreground leading-none md:hidden">
								{storeName}
							</p>
						</div>
					</div>
					<DropdownMenu>
						<DropdownMenuTrigger
							render={() => (
								<button
									className="flex h-9 w-9 cursor-pointer items-center justify-center rounded-full bg-primary/10 font-bold text-primary text-xs"
									type="button"
								>
									A
								</button>
							)}
						/>
						<DropdownMenuContent align="end" className="w-56 bg-card border border-border rounded-lg shadow-lg">
							<DropdownMenuLabel>Akun Admin</DropdownMenuLabel>
							<DropdownMenuSeparator />
							<DropdownMenuItem onClick={() => handleNavigate("/admin")}>
								<User className="mr-2 h-4 w-4" />
								<span>Profil</span>
							</DropdownMenuItem>
							<DropdownMenuSeparator />
							<DropdownMenuItem
								className="text-destructive"
								onClick={() => handleNavigate("/")}
							>
								<LogOut className="mr-2 h-4 w-4" />
								<span>Keluar</span>
							</DropdownMenuItem>
						</DropdownMenuContent>
					</DropdownMenu>
				</header>

				<div className="flex-1 overflow-y-auto p-3 pb-20 md:p-4 md:pb-4">
					<Outlet />
				</div>

				<footer className="border-border border-t bg-muted/20 px-4 py-2 text-center text-muted-foreground text-xs">
					{appName} {APP_VERSION.semantic}
				</footer>
			</main>

			{/* Mobile Quick Menu */}
			<AnimatePresence>
				{isQuickMenuOpen && (
					<>
						<motion.div
							animate={{ opacity: 1 }}
							className="fixed inset-0 z-40 bg-black/50 md:hidden"
							exit={{ opacity: 0 }}
							initial={{ opacity: 0 }}
							onClick={() => setIsQuickMenuOpen(false)}
						/>
						<motion.div
							animate={{ y: 0, opacity: 1 }}
							className="fixed right-0 bottom-0 left-0 z-50 rounded-t-2xl border-border border-t bg-card px-4 pt-4 pb-6 shadow-2xl md:hidden"
							exit={{ y: "100%", opacity: 0 }}
							initial={{ y: "100%", opacity: 0 }}
						>
							<div className="mx-auto mb-3 h-1 w-10 rounded-full bg-muted" />
							<div className="mb-4 flex items-center justify-between">
								<h3 className="font-semibold text-foreground">Menu</h3>
								<button
									className="flex h-7 w-7 items-center justify-center rounded-full bg-muted"
									onClick={() => setIsQuickMenuOpen(false)}
									type="button"
								>
									<X className="h-4 w-4" />
								</button>
							</div>
							<div className="grid grid-cols-4 gap-2">
								<button
									className="flex flex-col items-center gap-1 rounded-lg bg-muted p-2.5"
									onClick={() => { setIsQuickMenuOpen(false); handleNavigate("/admin"); }}
									type="button"
								>
									<LayoutDashboard className="h-5 w-5" />
									<span className="text-[10px]">Dasbor</span>
								</button>
								<button
									className="flex flex-col items-center gap-1 rounded-lg bg-destructive/10 p-2.5"
									onClick={() => { setIsQuickMenuOpen(false); handleNavigate("/"); }}
									type="button"
								>
									<LogOut className="h-5 w-5 text-destructive" />
									<span className="text-[10px] text-destructive">Keluar</span>
								</button>
							</div>
						</motion.div>
					</>
				)}
			</AnimatePresence>

			{/* Mobile Bottom Nav */}
			<nav className="safe-area-bottom fixed inset-x-0 bottom-0 z-30 border-border border-t bg-background/95 backdrop-blur-md md:hidden">
				<div className="flex items-stretch px-2">
					{BOTTOM_NAV_ITEMS.map((item) => {
						const isMore = "isMore" in item && item.isMore;
						const isActive = item.exact 
							? location.pathname === item.to 
							: location.pathname.startsWith(item.to);

						if (isMore) {
							return (
								<button
									className="flex flex-1 flex-col items-center justify-center gap-1 py-2"
									key="lainnya"
									onClick={() => setIsQuickMenuOpen(true)}
									type="button"
								>
									<div className={`flex h-7 w-7 items-center justify-center rounded-lg ${isQuickMenuOpen ? "bg-primary text-primary-foreground" : "text-muted-foreground"}`}>
										<item.icon className="h-4 w-4" />
									</div>
									<span className={`font-medium text-[9px] ${isQuickMenuOpen ? "text-primary" : "text-muted-foreground"}`}>
										{item.label}
									</span>
								</button>
							);
						}

						return (
							<button
								className="flex flex-1 flex-col items-center justify-center gap-1 py-2"
								key={item.to}
								onClick={() => handleNavigate(item.to)}
								type="button"
							>
								<div className={`flex h-7 w-7 items-center justify-center rounded-lg ${isActive ? "bg-primary text-primary-foreground" : "text-muted-foreground"}`}>
									<item.icon className="h-4 w-4" />
								</div>
								<span className={`font-medium text-[9px] ${isActive ? "text-primary" : "text-muted-foreground"}`}>
									{item.label}
								</span>
							</button>
						);
					})}
				</div>
			</nav>
		</div>
	);
}

function DesktopNavLink({
	icon,
	label,
	isCollapsed,
	onClick,
}: {
	icon: React.ReactNode;
	label: string;
	isCollapsed: boolean;
	onClick: () => void;
}) {
	return (
		<button
			className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 font-medium text-sm text-muted-foreground transition-all hover:bg-muted hover:text-foreground ${
				isCollapsed ? "justify-center px-0" : ""
			}`}
			onClick={onClick}
			title={isCollapsed ? label : undefined}
			type="button"
		>
			<span className="shrink-0 [&>svg]:h-5 [&>svg]:w-5">{icon}</span>
			{!isCollapsed && <span className="truncate">{label}</span>}
		</button>
	);
}
